s=s.replace('<picker v-if="mode===\'directory\'" :range="options" range-key="label" @change="selectProvince"><button class="outline">{{selectedLabel}} ⌄</button></picker>','<picker v-if="mode===\'directory\'" :value="options.findIndex(p=>p.code===code)" :range="options" range-key="label" @change="selectProvince"><button class="province-filter" aria-label="选择籍贯省份"><image src="/static/icons/pin.png" mode="aspectFit"/><text>{{selectedLabel}}</text><text class="filter-chevron">⌄</text></button></picker>')
start=s.index('<view class="directory-dossiers">');end=s.index('<view class="list-summary">',start)
s=s[:start]+'''<view class="directory-dossiers quick-directory"><button class="quick-toggle" :aria-expanded="quickOpen" aria-controls="quick-people" @tap="quickOpen=!quickOpen"><view><text class="quick-title">重点人物 · 快速阅读</text><text class="quick-subtitle">按出生地域分组，已计入全国名单，不重复计数。</text></view><view class="quick-toggle-end"><text class="quick-count">{{quickCount}}份档案</text><text class="quick-state">{{quickOpen?'收起':'展开'}} <text :class="['quick-chevron',{expanded:quickOpen}]">⌄</text></text></view></button><view v-if="quickOpen" id="quick-people" class="quick-content"><view v-for="section in quickSections" :key="section.name" class="quick-row"><text class="quick-region">{{section.name}}</text><view class="dossier-links"><button v-for="p in section.items" :key="p.id" class="dossier-link" @tap="go('person',{id:p.id})">{{p.name}}</button></view></view><text v-if="!quickCount" class="small">没有匹配的详细档案，可继续查看全国名单。</text></view></view>'''+s[end:]
