insert="const quickSections=computed(()=>[...new Set(dossiers.map(p=>p.province))].map(name=>({name:name==='待核'?'出生地域未载':name,items:dossiers.filter(p=>p.province===name&&matches(p))})).filter(s=>s.items.length));\nconst quickCount=computed(()=>quickSections.value.reduce((n,s)=>n+s.items.length,0));\n"
s=s.replace('const nameCounts=new Map();',insert+'const nameCounts=new Map();')
